            for r in conn.execute(f"SELECT * FROM warranties WHERE order_id IN ({oq})", order_ids)
        ]
        orders_per_customer: dict[str, int] = {}
        for r in order_rows:
            orders_per_customer[r["customer_id"]] = orders_per_customer.get(r["customer_id"], 0) + 1
        customers = [
